#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAException.h>
#include <cuda_bf16.h>

constexpr int CIN = 3;
constexpr int COUT = 32;
constexpr int K = 3;
constexpr int TILE = 32;
constexpr int THREADS = 16;
