    const __nv_bfloat16* __restrict__ x,
    const __nv_bfloat16* __restrict__ w,
    __nv_bfloat16* __restrict__ y,
    const int N,
    const int H,
    const int W,
    const int Ho,
    const int Wo) {
  __shared__ float sh_in[CIN][IN_TILE][IN_TILE];
  __shared__ float sh_w[COUT][CIN][K][K];

  const int tx = threadIdx.x;
  const int ty = threadIdx.y;
  const int tid = ty * blockDim.x + tx;
  const int nthreads = blockDim.x * blockDim.y;

  const int ow0 = blockIdx.x * TILE;
  const int oh0 = blockIdx.y * TILE;
  const int n = blockIdx.z;

  for (int idx = tid; idx < CIN * IN_TILE * IN_TILE; idx += nthreads) {
    const int ci = idx / (IN_TILE * IN_TILE);
    const int rem = idx - ci * (IN_TILE * IN_TILE);
    const int ih = rem / IN_TILE;
    const int iw = rem - ih * IN_TILE;
    const int gh = oh0 + ih;
    const int gw = ow0 + iw;

    float v = 0.0f;
    if (gh < H && gw < W) {
      const long long off =
          ((long long)n * CIN + ci) * (long long)H * W +
          (long long)gh * W + gw;
      v = __bfloat162float(x[off]);
    }
    sh_in[ci][ih][iw] = v;
  }

  float* shw = &sh_w[0][0][0][0];
  for (int idx = tid; idx < COUT * CIN * K * K; idx += nthreads) {
    shw[idx] = __bfloat162float(w[idx]);
  }

  __syncthreads();

  const int oh = oh0 + 2 * ty;
  const int ow = ow0 + 2 * tx;
  float r[CIN][K + 1][K + 1];
#pragma unroll
  for (int ci = 0; ci < CIN; ++ci) {
#pragma unroll
    for (int ih = 0; ih < K + 1; ++ih) {
#pragma unroll
      for (int iw = 0; iw < K + 1; ++iw) {
